const getPrefs=()=>{const saved=JSON.parse(localStorage.getItem('sportPrefs')||'null');return saved?.version===3?saved:{version:3,sports:[...sports],channels:channels.map(x=>x[0])}};
function renderEvents(filter='Alla'){const root=document.querySelector('#events');if(!root)return;const prefs=getPrefs();const allowed=e=>prefs.channels.some(c=>(c.startsWith('TV4')&&(e.service.includes('TV4')||e.channel.includes('TV4')))||(c.startsWith('Viaplay')&&e.service.includes('Viaplay'))||(c.startsWith('Disney')&&e.service.includes('Disney'))||(c.startsWith('HBO')&&(e.service.includes('HBO')||e.channel.includes('Eurosport')))||(c==='SVT'&&/^SVT\d|SVT24/.test(e.channel))||(c==='SVT Play'&&(e.service.includes('SVT')||e.channel.includes('SVT Play')))||(c==='Kanal 6'&&e.channel==='Kanal 6')||(c==='Kanal 9'&&e.channel==='Kanal 9')||(c==='Kanal 12'&&e.channel==='Kanal 12')||(c.startsWith('V sport')&&e.channel.startsWith('V sport')));const visible=events.filter(e=>prefs.sports.includes(e.sport)&&allowed(e)&&(filter==='Alla'||e.sport===filter));const eventRow=e=>`<a class="event" href="${e.url}" target="_blank" rel="noreferrer"><span class="time">${e.time}</span><div><span class="sport-label">${e.sport}</span><h4>${e.title}</h4><p>${e.meta}</p></div><div class="channel"><b>${e.channel}</b><span>${e.service}</span></div><span class="arrow">↗</span></a>`;if(root.dataset.view==='timeline'){const sorted=[...visible].sort((a,b)=>a.time.localeCompare(b.time)||a.title.localeCompare(b.title,'sv'));root.innerHTML=sorted.map(eventRow).join('')||'<div class="empty">Inga valda sändningar att visa.</div>';const count=document.querySelector('#count');if(count)count.textContent=visible.length;return}const groups=Object.groupBy?Object.groupBy(visible,e=>e.sport):visible.reduce((a,e)=>((a[e.sport]??=[]).push(e),a),{});root.innerHTML=Object.keys(groups).sort((a,b)=>a.localeCompare(b,'sv')).map(s=>`<section class="sport-group"><div class="sport-title"><h3>${s}</h3><span>${groups[s].length} SÄNDNING${groups[s].length>1?'AR':''}</span></div>${groups[s].sort((a,b)=>a.time.localeCompare(b.time)).map(eventRow).join('')}</section>`).join('')||'<div class="empty">Inga valda sändningar att visa.</div>';document.querySelector('#count').textContent=`${visible.length} sändningar`}
document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderEvents(b.dataset.filter)}));renderEvents();
const timelineView=document.querySelector('[data-view="timeline"]');if(timelineView){requestAnimationFrame(()=>{const rows=[...timelineView.querySelectorAll('.event')];if(!rows.length)return;const now=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const current=rows.find(row=>row.querySelector('.time').textContent>=now)||rows.at(-1);current.classList.add('current-event');current.scrollIntoView({block:'center'})})}
document.querySelector('#refresh')?.addEventListener('click',e=>{e.currentTarget.textContent='✓ Uppdaterad';setTimeout(()=>e.currentTarget.textContent='↻ Uppdatera nu',1800)});
function renderSettings(){const form=document.querySelector('#settings-form');if(!form)return;let prefs=getPrefs();const save=()=>{localStorage.setItem('sportPrefs',JSON.stringify(prefs));const s=document.querySelector('#save-status');s.textContent='✓ Ändringar sparade';};document.querySelector('#sports-options').innerHTML=sports.map(x=>`<label class="option"><input type="checkbox" value="${x}" ${prefs.sports.includes(x)?'checked':''}><span>${x}</span></label>`).join('');document.querySelector('#channel-options').innerHTML=channels.map(([x,d])=>`<label class="option"><input type="checkbox" value="${x}" ${prefs.channels.includes(x)?'checked':''}><span>${x}<small>${d}</small></span></label>`).join('');form.addEventListener('change',e=>{const all=[...form.querySelectorAll('input')];prefs={version:3,sports:all.filter(x=>sports.includes(x.value)&&x.checked).map(x=>x.value),channels:all.filter(x=>channels.some(c=>c[0]===x.value)&&x.checked).map(x=>x.value)};save()});document.querySelectorAll('[data-toggle]').forEach(b=>b.addEventListener('click',()=>{const vals=b.dataset.toggle==='sports'?sports:channels.map(x=>x[0]);form.querySelectorAll('input').forEach(i=>{if(vals.includes(i.value))i.checked=true});form.dispatchEvent(new Event('change'));}));}renderSettings();
